diff --git a/cmd/entire/cli/search/search.go b/cmd/entire/cli/search/search.go
index e28b80b9..9a6096dd 100644
--- a/cmd/entire/cli/search/search.go
+++ b/cmd/entire/cli/search/search.go
@@ -32,6 +32,16 @@ const v4ServicePath = "/api/v1/semantic-search/search/v1/search"
 // a "failed" region.
 var ErrCellUnavailable = errors.New("semantic search is not available in this cell")

+// ErrRepoFilterUnmatched reports that query-serve answered (the route exists)
+// but the explicit repo filter matched nothing the caller can search — the
+// repo isn't indexed yet, or its owner org isn't enabled on the
+// semantic-search feature flag (entire-search fails closed with a JSON 404,
+// existence not disclosed). A typo'd repo can't produce this from the CLI:
+// the slug was already resolved against the control-plane index before any
+// cell was contacted. Distinct from ErrCellUnavailable so fan-out callers
+// don't misreport a repo-level miss as a region without query-serve.
+var ErrRepoFilterUnmatched = errors.New("no requested repo was found in this cell")
+
 // WildcardQuery is the query string used when only filters are provided (no search terms).
 const WildcardQuery = "*"

@@ -667,10 +677,22 @@ func CellV4(ctx context.Context, client *api.Client, cfg Config, repoIDs []strin
 		return nil, fmt.Errorf("reading response: %w", err)
 	}
 	if resp.StatusCode == http.StatusNotFound {
-		// The gateway has no semantic-search route (plain "404 page not
-		// found") — query-serve isn't deployed in this cell. Deployed cells
-		// answer unknown repos with an empty 200, so a route-level 404 is
-		// distinctive.
+		// Two distinct 404s share this status. A JSON error body is
+		// query-serve answering through the gateway: the route exists but the
+		// repo filter matched nothing the caller may search (not indexed, or
+		// the owner org isn't flag-enabled — entire-search fails closed,
+		// existence not disclosed). A plain "404 page not found" is the
+		// gateway itself: no semantic-search route, query-serve not deployed
+		// in this cell. Deployed cells answer unfiltered searches of unknown
+		// repos with an empty 200, so the split is unambiguous.
+		var errResp struct {
+			Error string `json:"error"`
+		}
+		if json.Unmarshal(body, &errResp) == nil && errResp.Error != "" {
+			// Wrap rather than return the bare sentinel so the server's own
+			// message survives into debug logs; errors.Is still matches.
+			return nil, fmt.Errorf("%w: %s", ErrRepoFilterUnmatched, errResp.Error)
+		}
 		return nil, ErrCellUnavailable
 	}
 	return parseSearchResponse(resp.StatusCode, body)
diff --git a/cmd/entire/cli/search/search_v4_test.go b/cmd/entire/cli/search/search_v4_test.go
index d4e8851e..0cfe9c5b 100644
--- a/cmd/entire/cli/search/search_v4_test.go
+++ b/cmd/entire/cli/search/search_v4_test.go
@@ -6,6 +6,7 @@ import (
 	"errors"
 	"net/http"
 	"net/http/httptest"
+	"strings"
 	"testing"

 	"github.com/entireio/cli/cmd/entire/cli/api"
@@ -157,3 +158,54 @@ func TestCellV4_RouteNotFoundIsErrCellUnavailable(t *testing.T) {
 		t.Fatalf("err = %v, want ErrCellUnavailable", err)
 	}
 }
+
+// TestCellV4_RepoUnmatched404IsNotCellUnavailable covers the OTHER 404: the
+// route exists and query-serve answered, but the repo filter matched nothing
+// (not indexed, or the owner org isn't feature-flag enabled — entire-search
+// fails closed with a JSON 404 body). That must NOT be classified as
+// "query-serve isn't deployed in this cell", or an org merely missing from
+// the flag reads as a missing region to the user.
+func TestCellV4_RepoUnmatched404IsNotCellUnavailable(t *testing.T) {
+	t.Parallel()
+
+	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
+		w.WriteHeader(http.StatusNotFound)
+		writeTestJSON(w, `{"error": "None of the requested repos were found"}`)
+	}))
+	defer srv.Close()
+
+	_, err := CellV4(context.Background(), api.NewClientWithBaseURL("tok", srv.URL), Config{Query: "q"}, []string{"01JREPOA"})
+	if errors.Is(err, ErrCellUnavailable) {
+		t.Fatalf("err = %v, want NOT ErrCellUnavailable for a repo-unmatched JSON 404", err)
+	}
+	if !errors.Is(err, ErrRepoFilterUnmatched) {
+		t.Fatalf("err = %v, want ErrRepoFilterUnmatched", err)
+	}
+	if !strings.Contains(err.Error(), "None of the requested repos were found") {
+		t.Errorf("err = %v, want the server's own message preserved in the wrap", err)
+	}
+}
+
+// TestCellV4_ProblemJSON404IsCellUnavailable pins the THIRD 404 shape: the
+// gateway's anonymous path writes RFC 7807 problem+json (title/status/detail
+// keys, no "error" key). Nothing in that body marks query-serve as having
+// answered, so it must fall through to ErrCellUnavailable rather than read as
+// a repo-filter miss.
+func TestCellV4_ProblemJSON404IsCellUnavailable(t *testing.T) {
+	t.Parallel()
+
+	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
+		w.Header().Set("Content-Type", "application/problem+json")
+		w.WriteHeader(http.StatusNotFound)
+		w.Write([]byte(`{"title":"Not Found","status":404,"detail":"no route for this path"}`)) //nolint:errcheck // test helper
+	}))
+	defer srv.Close()
+
+	_, err := CellV4(context.Background(), api.NewClientWithBaseURL("tok", srv.URL), Config{Query: "q"}, []string{"01JREPOA"})
+	if !errors.Is(err, ErrCellUnavailable) {
+		t.Fatalf("err = %v, want ErrCellUnavailable for a problem+json 404", err)
+	}
+	if errors.Is(err, ErrRepoFilterUnmatched) {
+		t.Fatalf("err = %v, want NOT ErrRepoFilterUnmatched for a problem+json 404", err)
+	}
+}
diff --git a/cmd/entire/cli/search_v4.go b/cmd/entire/cli/search_v4.go
index 77b2424a..307c70df 100644
--- a/cmd/entire/cli/search_v4.go
+++ b/cmd/entire/cli/search_v4.go
@@ -341,11 +341,18 @@ type semanticCellPage struct {
 // cluster catalog doesn't expose the placement's jurisdiction at all (a cell
 // mid-onboarding). Neither is worth warning the user about on every search.
 func classifySemanticCells(ctx context.Context, results []cellCallResult[*search.Response]) (pages []semanticCellPage, failed []string, lastErr error) {
-	var skipped []string
+	var skipped, unmatched []string
+	var unmatchedErr error
 	for _, r := range results {
 		switch {
 		case errors.Is(r.err, search.ErrCellUnavailable), errors.Is(r.err, auth.ErrNoCellForJurisdiction):
 			skipped = append(skipped, r.group.label())
+		case errors.Is(r.err, search.ErrRepoFilterUnmatched):
+			// The cell answered; the repo filter just matched nothing there.
+			// Quiet like a skip when another cell has results, but if NO cell
+			// matches it must surface as a repo problem, never a region one.
+			unmatched = append(unmatched, r.group.label())
+			unmatchedErr = r.err
 		case r.err != nil:
 			lastErr = r.err
 			failed = append(failed, r.group.label())
@@ -365,12 +372,31 @@ func classifySemanticCells(ctx context.Context, results []cellCallResult[*search
 	if len(skipped) > 0 {
 		logging.Debug(ctx, "semantic search: cells without query-serve skipped", "skipped_cells", skipped)
 	}
-	if len(pages) == 0 && lastErr == nil && len(skipped) > 0 {
-		lastErr = errNoRegionAvailable
+	if len(unmatched) > 0 {
+		// unmatchedErr carries the server's own message (CellV4 wraps it into
+		// the sentinel) — keep it visible here for diagnosis.
+		logging.Debug(ctx, "semantic search: cells where the repo filter matched nothing", "unmatched_cells", unmatched, "error", unmatchedErr.Error())
+	}
+	if len(pages) == 0 && lastErr == nil {
+		switch {
+		case len(unmatched) > 0:
+			// Takes priority over the region message: a cell answering proves
+			// its region serves semantic search.
+			lastErr = errNoRepoAvailable
+		case len(skipped) > 0:
+			lastErr = errNoRegionAvailable
+		}
 	}
 	return pages, failed, lastErr
 }

+// errNoRepoAvailable is returned when at least one cell answered but none
+// matched the repo filter. A typo'd name or missing access cannot reach this
+// point — resolveScope already validated the slug against the control-plane
+// repo index — so the message names only the causes that survive: query-serve
+// hasn't indexed the repo, or its owner org isn't enabled for semantic search.
+var errNoRepoAvailable = errors.New("semantic search cannot search this repo yet — it may not be indexed, or semantic search may not be enabled for its owner")
+
 // errNoRegionAvailable is returned when every queried cell lacks query-serve.
 var errNoRegionAvailable = errors.New("semantic search is not yet available in the region(s) hosting this search")

diff --git a/cmd/entire/cli/search_v4_test.go b/cmd/entire/cli/search_v4_test.go
index faaf3f1d..bfcdbfea 100644
--- a/cmd/entire/cli/search_v4_test.go
+++ b/cmd/entire/cli/search_v4_test.go
@@ -542,3 +542,70 @@ func TestNewSemanticSearcher_RejectsMultipleRepoFilters(t *testing.T) {
 		t.Fatal("expected a validation error before any network access")
 	}
 }
+
+// TestMergeSemanticV4Responses_AllCellsRepoUnmatched verifies the error when
+// every queried cell answered but none matched the repo filter (not indexed,
+// or the owner org isn't flag-enabled — a typo can't reach this point, the
+// slug already resolved). The old behavior lumped this in with undeployed
+// cells and told the user their REGION lacked semantic search — a
+// misdiagnosis that sent a flag-enrollment gap to the wrong team.
+func TestMergeSemanticV4Responses_AllCellsRepoUnmatched(t *testing.T) {
+	t.Parallel()
+
+	_, err := mergeSemanticV4Responses(context.Background(), 0, 0, []cellCallResult[*search.Response]{
+		v4CellErr(fmt.Errorf("cell a: %w", search.ErrRepoFilterUnmatched)),
+		v4CellErr(search.ErrRepoFilterUnmatched),
+	})
+	if err == nil {
+		t.Fatal("expected an error when no cell matched the repo filter")
+	}
+	if strings.Contains(err.Error(), "region") {
+		t.Errorf("error = %q, must not blame the region for a repo-filter miss", err.Error())
+	}
+	if !strings.Contains(err.Error(), "repo") || !strings.Contains(err.Error(), "enabled") {
+		t.Errorf("error = %q, want it to point at the repo name, access, or semantic-search enablement", err.Error())
+	}
+}
+
+// TestMergeSemanticV4Responses_RepoUnmatchedBeatsRegionMessage: when some
+// cells lack query-serve AND one answered "repo unmatched", the repo message
+// wins — a cell answering proves the region serves semantic search.
+func TestMergeSemanticV4Responses_RepoUnmatchedBeatsRegionMessage(t *testing.T) {
+	t.Parallel()
+
+	_, err := mergeSemanticV4Responses(context.Background(), 0, 0, []cellCallResult[*search.Response]{
+		v4CellErr(search.ErrCellUnavailable),
+		v4CellErr(search.ErrRepoFilterUnmatched),
+	})
+	if err == nil {
+		t.Fatal("expected an error")
+	}
+	if strings.Contains(err.Error(), "region") {
+		t.Errorf("error = %q, must not blame the region when a cell answered", err.Error())
+	}
+}
+
+// TestMergeSemanticV4Responses_RepoUnmatchedQuietWithResults: a repo-unmatched
+// cell alongside a successful page is skipped quietly, like an undeployed
+// cell — no partial-failure warning, results still returned.
+func TestMergeSemanticV4Responses_RepoUnmatchedQuietWithResults(t *testing.T) {
+	t.Parallel()
+
+	ok := &search.Response{Results: []search.Result{
+		v4Ckpt("ok", 1, search.Meta{Score: 0.5}),
+	}, Total: 1}
+
+	resp, err := mergeSemanticV4Responses(context.Background(), 0, 0, []cellCallResult[*search.Response]{
+		v4CellErr(search.ErrRepoFilterUnmatched),
+		v4CellOK(ok),
+	})
+	if err != nil {
+		t.Fatal(err)
+	}
+	if len(resp.Warnings) != 0 {
+		t.Errorf("warnings = %v, want none for a repo-unmatched cell beside results", resp.Warnings)
+	}
+	if len(resp.Results) != 1 {
+		t.Errorf("results = %d, want 1", len(resp.Results))
+	}
+}

